/**
 * Builds the reference data shipped with the static site:
 *  - public/data/states.json : 50 states + DC (US Census boundaries via us-atlas)
 *  - public/data/cities.json : US places with population ≥ 1,000 (GeoNames via all-the-cities, CC BY 4.0)
 * Run with: npm run data
 */
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
mkdirSync("public/data", { recursive: true });

// State boundaries are generated by the main app's build-geo script; reuse them.
copyFileSync("../public/geo/states.json", "public/data/states.json");

const CODES = new Set(JSON.parse(readFileSync("public/data/states.json", "utf8")).features.map((f) => f.properties.code));
const SKIP = new Set(["PPLX", "PPLQ", "PPLH", "PPLW", "PPLCH"]);
const rows = require("all-the-cities")
  .filter((c) => c.country === "US" && CODES.has(c.adminCode) && !SKIP.has(c.featureCode))
  .sort((a, b) => b.population - a.population);

const r4 = (v) => Math.round(v * 1e4) / 1e4;
writeFileSync(
  "public/data/cities.json",
  JSON.stringify({
    source: "GeoNames (CC BY 4.0) via all-the-cities",
    ids: rows.map((c) => c.cityId),
    names: rows.map((c) => c.name),
    states: rows.map((c) => c.adminCode),
    lon: rows.map((c) => r4(c.loc.coordinates[0])),
    lat: rows.map((c) => r4(c.loc.coordinates[1])),
    pop: rows.map((c) => c.population),
  }),
);
console.log(`cities: ${rows.length}`);
